//! Public sequence entropy and frame-state regressions.
//!
//! The independent inspector reads wire headers and sequence modes, without
//! accessing private encoder tables or requiring upstream strategy identity.
//! Singleton normalized headers were generated by facebook/zstd v1.5.7's
//! `FSE_writeNCount`; source attribution and terms are in LICENSE.zstd.
#![forbid(unsafe_code)]

use zstdoxide::{
    DecodeOptions, Dictionary, Encoder, EncoderOptions, EndDirective, FrameHeader,
    SharedDictionary, StreamStatus, compress, compress_with_dictionary, decompress,
    decompress_with_dictionary,
};

#[derive(Debug)]
struct Section<'a> {
    count: usize,
    modes: Option<[u8; 3]>,
    bytes: &'a [u8],
}

#[derive(Debug)]
struct Block<'a> {
    kind: u8,
    literal_kind: Option<u8>,
    sequences: Option<Section<'a>>,
}

fn little_endian(bytes: &[u8]) -> u64 {
    assert!(bytes.len() <= 5);
    bytes.iter().enumerate().fold(0, |value, (index, &byte)| {
        value | (u64::from(byte) << (8 * index))
    })
}

/// Read only initialized frame slices. Every slice boundary is checked by the
/// test process, independently of the production encoder's private metadata.
fn blocks(frame: &[u8]) -> Vec<Block<'_>> {
    let (header, mut position) = FrameHeader::parse(frame).unwrap();
    let mut blocks = Vec::new();
    loop {
        let value = little_endian(frame.get(position..position + 3).unwrap());
        position += 3;
        let kind = ((value >> 1) & 3) as u8;
        assert!(kind < 3);
        let size = usize::try_from(value >> 3).unwrap();
        assert!(size <= 128 * 1024 && size as u64 <= header.window_size);
        let stored = if kind == 1 { 1 } else { size };
        let payload = frame.get(position..position + stored).unwrap();
        position += stored;
        let (literal_kind, sequences) = if kind == 2 {
            let literal_kind = payload[0] & 3;
            let format = (payload[0] >> 2) & 3;
            let section_size = if literal_kind < 2 {
                let (width, shift) = match format {
                    0 | 2 => (1, 3),
                    1 => (2, 4),
                    _ => (3, 4),
                };
                let regenerated =
                    usize::try_from(little_endian(&payload[..width]) >> shift).unwrap();
                assert!(regenerated <= 128 * 1024);
                width + if literal_kind == 1 { 1 } else { regenerated }
            } else {
                let (width, bits) = match format {
                    0 | 1 => (3, 10),
                    2 => (4, 14),
                    _ => (5, 18),
                };
                let value = little_endian(&payload[..width]);
                let regenerated = (value >> 4) & ((1 << bits) - 1);
                assert!(regenerated <= 128 * 1024);
                width + usize::try_from(value >> (4 + bits)).unwrap()
            };
            let bytes = payload.get(section_size..).unwrap();
            let (count, width) = match bytes[0] {
                byte @ 0..=127 => (usize::from(byte), 1),
                byte @ 128..=254 => (((usize::from(byte) - 128) << 8) + usize::from(bytes[1]), 2),
                _ => (
                    usize::try_from(little_endian(&bytes[1..3])).unwrap() + 0x7f00,
                    3,
                ),
            };
            assert!(count <= 128 * 1024 / 3);
            let modes = if count == 0 {
                assert_eq!(
                    bytes,
                    &[0],
                    "empty sequence sections have no mode or bitstream"
                );
                None
            } else {
                let mode = bytes[width];
                assert_eq!(mode & 3, 0);
                assert!(
                    bytes.len() > width + 1,
                    "nonempty sequence stream has a marker"
                );
                Some([mode >> 6, (mode >> 4) & 3, (mode >> 2) & 3])
            };
            (
                Some(literal_kind),
                Some(Section {
                    count,
                    modes,
                    bytes,
                }),
            )
        } else {
            (None, None)
        };
        blocks.push(Block {
            kind,
            literal_kind,
            sequences,
        });
        if value & 1 != 0 {
            break;
        }
    }
    assert_eq!(
        position + if header.has_checksum { 4 } else { 0 },
        frame.len()
    );
    blocks
}

fn action(encoder: &mut Encoder, input: &[u8], directive: EndDirective, chunk: usize) -> Vec<u8> {
    assert!(chunk > 0);
    let before_input = encoder.total_input();
    let before_output = encoder.total_output();
    let mut consumed = 0;
    let mut encoded = Vec::new();
    for call in 1..1_000_000 {
        let capacity = if call % 7 == 0 { 0 } else { chunk };
        let mut output = vec![0xa5; capacity + 8];
        let progress = encoder
            .process(&input[consumed..], &mut output[..capacity], directive)
            .unwrap();
        assert!(progress.consumed <= input.len() - consumed && progress.produced <= capacity);
        assert!(output[progress.produced..].iter().all(|&byte| byte == 0xa5));
        consumed += progress.consumed;
        encoded.extend_from_slice(&output[..progress.produced]);
        assert_eq!(encoder.total_input(), before_input + consumed as u64);
        assert_eq!(encoder.total_output(), before_output + encoded.len() as u64);
        let done = match directive {
            EndDirective::Continue => progress.status == StreamStatus::NeedInput,
            EndDirective::Flush => progress.status == StreamStatus::Flushed,
            EndDirective::Finish => progress.status == StreamStatus::FrameFinished,
        };
        if done {
            assert_eq!(consumed, input.len());
            return encoded;
        }
        assert_eq!(progress.status, StreamStatus::NeedOutput);
        assert!(progress.consumed != 0 || progress.produced != 0 || capacity == 0);
    }
    panic!("sequence encoder exceeded bounded call count");
}

fn encode_blocks(
    encoder: &mut Encoder,
    sources: &[Vec<u8>],
    input_chunk: usize,
    output_chunk: usize,
) -> Vec<u8> {
    assert!(!sources.is_empty() && input_chunk > 0);
    let mut frame = Vec::new();
    for (index, source) in sources.iter().enumerate() {
        for part in source.chunks(input_chunk) {
            frame.extend(action(encoder, part, EndDirective::Continue, output_chunk));
        }
        frame.extend(action(
            encoder,
            &[],
            if index + 1 == sources.len() {
                EndDirective::Finish
            } else {
                EndDirective::Flush
            },
            output_chunk,
        ));
    }
    assert_eq!(
        encoder.total_input(),
        sources
            .iter()
            .map(|source| source.len() as u64)
            .sum::<u64>()
    );
    assert_eq!(encoder.total_output(), frame.len() as u64);
    frame
}

fn runs(first: u8, count: usize, varied: bool) -> Vec<u8> {
    (0..count)
        .flat_map(|index| {
            std::iter::repeat_n(first + index as u8, if varied { 8 + index % 7 } else { 20 })
        })
        .collect()
}

fn unique_keys(size: usize, base: u8) -> Vec<u8> {
    fn visit(depth: usize, period: usize, word: &mut [u8; 5], out: &mut Vec<u8>) {
        if depth == word.len() {
            if 4 % period == 0 {
                out.extend_from_slice(&word[1..=period]);
            }
        } else {
            word[depth] = word[depth - period];
            visit(depth + 1, period, word, out);
            for next in word[depth - period] + 1..16 {
                word[depth] = next;
                visit(depth + 1, depth, word, out);
            }
        }
    }
    let mut out = Vec::new();
    visit(1, 1, &mut [0; 5], &mut out);
    assert_eq!(out.len(), 65_536);
    out.truncate(size);
    for byte in &mut out {
        *byte += base;
    }
    let mut seen = std::collections::BTreeSet::new();
    assert!(out.windows(4).all(|word| seen.insert(word)));
    out
}

fn preservation_sources() -> Vec<Vec<u8>> {
    vec![
        runs(0, 64, false),
        b"UVWXUVWX".to_vec(),
        vec![254; 256],
        unique_keys(4096, 160),
        runs(64, 64, false),
    ]
}

fn singleton_dictionary(runs: bool) -> SharedDictionary {
    let mut bytes = 0xec30_a437_u32.to_le_bytes().to_vec();
    bytes.extend_from_slice(&12345_u32.to_le_bytes());
    bytes.extend_from_slice(&[128, 0x10]);
    // Exact v1.5.7 FSE_writeNCount output: OF symbol0; ML symbol16 or29;
    // LL symbol1 or0. Each normalized singleton retains tableLog5.
    bytes.extend_from_slice(&[0xf0, 0x03]);
    bytes.extend_from_slice(if runs {
        &[0x10, 0xfe, 0xe7, 0x07]
    } else {
        &[0x10, 0xfe, 0xff, 0xef, 0x07]
    });
    bytes.extend_from_slice(if runs {
        &[0x10, 0xf8, 0x01]
    } else {
        &[0xf0, 0x03]
    });
    for _ in 0..3 {
        bytes.extend_from_slice(&(if runs { 1_u32 } else { 8_u32 }).to_le_bytes());
    }
    if runs {
        bytes.extend(128..192);
    } else {
        bytes.extend_from_slice(b"abcdABCD");
    }
    Dictionary::from_bytes(&bytes).unwrap().into_shared()
}

fn assert_sequence_modes(frame: &[u8], expected: &[(usize, [u8; 3])]) {
    let parsed = blocks(frame);
    assert_eq!(parsed.len(), expected.len(), "{parsed:?}");
    for (block, &(count, modes)) in parsed.iter().zip(expected) {
        assert_eq!(block.kind, 2, "{parsed:?}");
        let section = block.sequences.as_ref().unwrap();
        assert_eq!(
            (section.count, section.modes),
            (count, Some(modes)),
            "{parsed:?}"
        );
    }
}

fn assert_preservation(frame: &[u8]) {
    let parsed = blocks(frame);
    assert_eq!(parsed.len(), 5, "{parsed:?}");
    assert_eq!(
        parsed.iter().map(|block| block.kind).collect::<Vec<_>>(),
        [2, 0, 1, 2, 2]
    );
    let first = parsed[0].sequences.as_ref().unwrap();
    assert_eq!((first.count, first.modes), (64, Some([1; 3])));
    assert_eq!(first.bytes, &[64, 0x54, 1, 0, 16, 1]);
    let empty = parsed[3].sequences.as_ref().unwrap();
    assert_eq!(parsed[3].literal_kind, Some(2));
    assert_eq!((empty.count, empty.modes, empty.bytes), (0, None, &[0][..]));
    let last = parsed[4].sequences.as_ref().unwrap();
    assert_eq!((last.count, last.modes), (64, Some([3; 3])));
    // Reused inline RLE channels consume zero state/transition/extra bits;
    // the only bitstream byte is its terminal marker. Dictionary normalized
    // singleton channels below deliberately consume their actual log5 states.
    assert_eq!(last.bytes, &[64, 0xfc, 1]);
}

fn replacement_sources() -> Vec<Vec<u8>> {
    vec![
        b"abcdABCD".repeat(4),
        runs(0, 64, false),
        b"abcdABCD".repeat(4),
        b"abcdABCD".repeat(4),
    ]
}

#[test]
fn public_one_shot_emits_predefined_rle_and_adaptive_sequence_tables() {
    for (source, count, modes) in [
        (b"abcdefghijklmnop".repeat(64), 1, [0; 3]),
        (runs(0, 64, false), 64, [1; 3]),
        (runs(0, 128, true), 128, [1, 1, 2]),
    ] {
        let frame = compress(&source).unwrap();
        assert_sequence_modes(&frame, &[(count, modes)]);
        assert!(frame.len() < source.len() / 2);
        assert_eq!(decompress(&frame, source.len()).unwrap(), source);
    }
}

#[test]
fn emitted_predefined_and_adaptive_tables_become_repeat_sources() {
    for (sources, counts, first_modes) in [
        (
            vec![
                b"abcdefghijklmnop".repeat(64),
                b"qrstuvwxyzABCDEF".repeat(64),
            ],
            [1, 1],
            [0; 3],
        ),
        (
            vec![runs(0, 128, true), runs(128, 128, true)],
            [128, 128],
            [1, 1, 2],
        ),
    ] {
        let frame = encode_blocks(&mut Encoder::new(), &sources, 4096, 4096);
        assert_sequence_modes(&frame, &[(counts[0], first_modes), (counts[1], [3; 3])]);
        let expected = sources.concat();
        assert_eq!(decompress(&frame, expected.len()).unwrap(), expected);
    }
}

#[test]
fn raw_rle_and_zero_sequence_blocks_preserve_tables_and_repeat_offsets() {
    let sources = preservation_sources();
    // A four-byte match is legal in the tiny raw witness, but its encoded
    // candidate loses to raw output. A longer copy demonstrates that the same
    // key reaches the public parser and produces a real distance-four match.
    let control = compress(&b"UVWX".repeat(8)).unwrap();
    assert_sequence_modes(&control, &[(1, [0; 3])]);
    let frame = encode_blocks(&mut Encoder::new(), &sources, 4096, 4096);
    assert_preservation(&frame);
    let expected = sources.concat();
    assert_eq!(decompress(&frame, expected.len()).unwrap(), expected);
}

#[test]
fn prepared_singletons_and_duplicate_repeats_preserve_their_real_state_widths() {
    // The second source matches all 32 bytes from an eight-byte dictionary
    // pattern with overlapping output: LL0, ML32, distance 8. With [8,8,8]
    // repeats the zero-literal remapping selects wire offset 1 (rep1), so OF0
    // is valid. This exercises a dictionary match through the public parser.
    for (dictionary, sources, count) in [
        (singleton_dictionary(true), vec![runs(0, 64, false)], 64),
        (singleton_dictionary(false), vec![b"abcdABCD".repeat(4)], 1),
    ] {
        let mut encoder =
            Encoder::with_dictionary(EncoderOptions::default(), dictionary.clone()).unwrap();
        let frame = encode_blocks(&mut encoder, &sources, 7, 13);
        assert_sequence_modes(&frame, &[(count, [3; 3])]);
        assert_eq!(
            blocks(&frame)[0].sequences.as_ref().unwrap().bytes,
            &[count as u8, 0xfc, 0, 0x80]
        );
        assert_eq!(FrameHeader::parse(&frame).unwrap().0.dictionary_id, 12345);
        let expected = sources.concat();
        assert_eq!(
            decompress_with_dictionary(&frame, &dictionary, DecodeOptions::new(expected.len()))
                .unwrap(),
            expected
        );
        let one_shot = compress_with_dictionary(&expected, &dictionary).unwrap();
        assert_sequence_modes(&one_shot, &[(count, [3; 3])]);
        assert_eq!(
            blocks(&one_shot)[0].sequences.as_ref().unwrap().bytes,
            &[count as u8, 0xfc, 0, 0x80]
        );
        assert_eq!(
            decompress_with_dictionary(&one_shot, &dictionary, DecodeOptions::new(expected.len()))
                .unwrap(),
            expected
        );
    }
}

#[test]
fn new_sequence_tables_replace_dictionary_tables_per_channel() {
    let dictionary = singleton_dictionary(false);
    let sources = replacement_sources();
    let mut encoder =
        Encoder::with_dictionary(EncoderOptions::default(), dictionary.clone()).unwrap();
    let frame = encode_blocks(&mut encoder, &sources, 4096, 4096);
    assert_sequence_modes(
        &frame,
        &[(1, [3; 3]), (64, [1, 2, 1]), (2, [1, 0, 0]), (1, [3; 3])],
    );
    // The initial dictionary LL0 table would be eligible and cheaper at the
    // third block. LL mode1 proves that the emitted LL1 table replaced it;
    // a stale dictionary fallback would incorrectly choose repeat mode3.
    let expected = sources.concat();
    assert_eq!(
        decompress_with_dictionary(&frame, &dictionary, DecodeOptions::new(expected.len()))
            .unwrap(),
        expected
    );
}

#[test]
fn reset_restores_persistent_dictionary_state_but_drops_claimed_prefix_state() {
    let dictionary = singleton_dictionary(false);
    let sources = vec![b"abcdABCD".repeat(4)];
    let mut persistent =
        Encoder::with_dictionary(EncoderOptions::default(), dictionary.clone()).unwrap();
    let changed = encode_blocks(&mut persistent, &replacement_sources(), 4096, 4096);
    assert_sequence_modes(
        &changed,
        &[(1, [3; 3]), (64, [1, 2, 1]), (2, [1, 0, 0]), (1, [3; 3])],
    );
    persistent.reset();
    let restored = encode_blocks(&mut persistent, &sources, 7, 13);
    assert_sequence_modes(&restored, &[(1, [3; 3])]);
    let mut fresh =
        Encoder::with_dictionary(EncoderOptions::default(), dictionary.clone()).unwrap();
    assert_eq!(restored, encode_blocks(&mut fresh, &sources, 4096, 4096));

    let mut prefix = Encoder::new();
    prefix.set_prefix(dictionary.clone()).unwrap();
    prefix.reset(); // An unclaimed prefix survives a session reset.
    let claimed = encode_blocks(&mut prefix, &sources, 1, 1);
    assert_eq!(claimed, restored);
    assert_eq!(
        decompress_with_dictionary(&claimed, &dictionary, DecodeOptions::new(32)).unwrap(),
        sources[0]
    );
    prefix.reset();
    let without_prefix = encode_blocks(&mut prefix, &sources, 1, 1);
    assert_eq!(
        FrameHeader::parse(&without_prefix).unwrap().0.dictionary_id,
        0
    );
    assert_sequence_modes(&without_prefix, &[(1, [0; 3])]);
    assert_eq!(
        without_prefix,
        encode_blocks(&mut Encoder::new(), &sources, 4096, 4096)
    );
    assert_eq!(decompress(&without_prefix, 32).unwrap(), sources[0]);

    let mut plain = Encoder::new();
    let run_source = vec![runs(0, 64, false)];
    let first = encode_blocks(&mut plain, &run_source, 4096, 4096);
    plain.reset();
    let reset = encode_blocks(&mut plain, &run_source, 7, 13);
    assert_sequence_modes(&reset, &[(64, [1; 3])]);
    assert_eq!(first, reset);
}

#[test]
fn input_and_output_fragmentation_preserve_every_sequence_section() {
    for (sources, dictionary) in [
        (preservation_sources(), None),
        (replacement_sources(), Some(singleton_dictionary(false))),
    ] {
        let expected = sources.concat();
        let mut baseline = None;
        for (input_chunk, output_chunk) in [(4096, 4096), (7, 13), (1, 1)] {
            let mut encoder = if let Some(dictionary) = &dictionary {
                Encoder::with_dictionary(EncoderOptions::default(), dictionary.clone()).unwrap()
            } else {
                Encoder::new()
            };
            let frame = encode_blocks(&mut encoder, &sources, input_chunk, output_chunk);
            if let Some(dictionary) = &dictionary {
                assert_sequence_modes(
                    &frame,
                    &[(1, [3; 3]), (64, [1, 2, 1]), (2, [1, 0, 0]), (1, [3; 3])],
                );
                assert_eq!(
                    decompress_with_dictionary(
                        &frame,
                        dictionary,
                        DecodeOptions::new(expected.len())
                    )
                    .unwrap(),
                    expected
                );
            } else {
                assert_preservation(&frame);
                assert_eq!(decompress(&frame, expected.len()).unwrap(), expected);
            }
            if let Some(baseline) = &baseline {
                assert_eq!(&frame, baseline);
            } else {
                baseline = Some(frame);
            }
        }
    }
}

#[cfg(feature = "std")]
mod oracle {
    use super::*;
    use std::io::Write;
    use std::path::{Path, PathBuf};
    use std::process::{Command, Stdio};

    fn executable() -> PathBuf {
        let upstream = PathBuf::from(
            std::env::var_os("ZSTD_UPSTREAM")
                .expect("set ZSTD_UPSTREAM to the pinned v1.5.7 checkout"),
        );
        let revision = Command::new("git")
            .arg("-C")
            .arg(&upstream)
            .args(["rev-parse", "HEAD"])
            .output()
            .unwrap();
        assert!(revision.status.success());
        assert_eq!(
            String::from_utf8(revision.stdout).unwrap().trim(),
            "f8745da6ff1ad1e7bab384bd1f9d742439278e99"
        );
        assert!(
            Command::new("git")
                .arg("-C")
                .arg(&upstream)
                .args(["diff", "--quiet", "HEAD", "--", "lib", "programs"])
                .status()
                .unwrap()
                .success(),
            "upstream library and CLI sources must be clean"
        );
        let executable = upstream.join("programs/zstd");
        let version = Command::new(&executable).arg("--version").output().unwrap();
        assert!(version.status.success());
        assert!(String::from_utf8_lossy(&version.stdout).contains("v1.5.7"));
        executable
    }

    fn decode(
        executable: &Path,
        label: &str,
        frame: &[u8],
        expected: &[u8],
        dictionary: Option<&Path>,
    ) {
        let mut command = Command::new(executable);
        command.args(["-q", "-d", "-c"]);
        if let Some(dictionary) = dictionary {
            command.arg("-D").arg(dictionary);
        }
        let mut child = command
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        let output = std::thread::scope(|scope| {
            let mut input = child.stdin.take().unwrap();
            let writer = scope.spawn(move || input.write_all(frame));
            let output = child.wait_with_output().unwrap();
            writer.join().unwrap().unwrap();
            output
        });
        assert!(
            output.status.success(),
            "{label}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert_eq!(output.stdout, expected, "{label}");
    }

    struct TemporaryDirectory(PathBuf);
    impl TemporaryDirectory {
        fn new() -> Self {
            let path = std::env::temp_dir().join(format!(
                "zstdoxide-public-sequences-{}-{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_nanos()
            ));
            std::fs::create_dir(&path).unwrap();
            Self(path)
        }
    }
    impl Drop for TemporaryDirectory {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    #[ignore = "requires ZSTD_UPSTREAM pinned v1.5.7 with its programs/zstd executable"]
    fn official_decoder_accepts_public_sequence_modes_and_dictionary_lifetimes() {
        let executable = executable();
        let directory = TemporaryDirectory::new();
        let mut checked_frames = 0;
        let mut checked_bytes = 0;
        let mut check = |label: &str, frame: &[u8], expected: &[u8], dictionary: Option<&Path>| {
            decode(&executable, label, frame, expected, dictionary);
            checked_frames += 1;
            checked_bytes += expected.len();
        };
        for (source, count, modes) in [
            (b"abcdefghijklmnop".repeat(64), 1, [0; 3]),
            (runs(0, 64, false), 64, [1; 3]),
            (runs(0, 128, true), 128, [1, 1, 2]),
        ] {
            let frame = compress(&source).unwrap();
            assert_sequence_modes(&frame, &[(count, modes)]);
            check("one-shot distribution", &frame, &source, None);
        }
        for (sources, counts, first_modes) in [
            (
                vec![
                    b"abcdefghijklmnop".repeat(64),
                    b"qrstuvwxyzABCDEF".repeat(64),
                ],
                [1, 1],
                [0; 3],
            ),
            (
                vec![runs(0, 128, true), runs(128, 128, true)],
                [128, 128],
                [1, 1, 2],
            ),
        ] {
            let frame = encode_blocks(&mut Encoder::new(), &sources, 7, 13);
            assert_sequence_modes(&frame, &[(counts[0], first_modes), (counts[1], [3; 3])]);
            check(
                "predefined/adaptive then repeat",
                &frame,
                &sources.concat(),
                None,
            );
        }
        let sources = preservation_sources();
        let frame = encode_blocks(&mut Encoder::new(), &sources, 1, 1);
        assert_preservation(&frame);
        check(
            "raw/RLE/zero-sequence preservation",
            &frame,
            &sources.concat(),
            None,
        );
        for (name, dictionary, source, count) in [
            ("runs", singleton_dictionary(true), runs(0, 64, false), 64),
            (
                "seed",
                singleton_dictionary(false),
                b"abcdABCD".repeat(4),
                1,
            ),
        ] {
            let path = directory.0.join(format!("{name}.dict"));
            std::fs::write(&path, dictionary.as_bytes()).unwrap();
            let one_shot = compress_with_dictionary(&source, &dictionary).unwrap();
            assert_sequence_modes(&one_shot, &[(count, [3; 3])]);
            check(
                "prepared one-shot singleton",
                &one_shot,
                &source,
                Some(&path),
            );
            let mut encoder =
                Encoder::with_dictionary(EncoderOptions::default(), dictionary.clone()).unwrap();
            let frame = encode_blocks(&mut encoder, std::slice::from_ref(&source), 1, 1);
            assert_sequence_modes(&frame, &[(count, [3; 3])]);
            check("prepared streaming singleton", &frame, &source, Some(&path));
        }
        let dictionary = singleton_dictionary(false);
        let path = directory.0.join("seed.dict");
        let mut encoder =
            Encoder::with_dictionary(EncoderOptions::default(), dictionary.clone()).unwrap();
        let sources = replacement_sources();
        let frame = encode_blocks(&mut encoder, &sources, 7, 13);
        assert_sequence_modes(
            &frame,
            &[(1, [3; 3]), (64, [1, 2, 1]), (2, [1, 0, 0]), (1, [3; 3])],
        );
        check(
            "dictionary channel replacement",
            &frame,
            &sources.concat(),
            Some(&path),
        );
        encoder.reset();
        let sources = vec![b"abcdABCD".repeat(4)];
        let restored = encode_blocks(&mut encoder, &sources, 1, 1);
        assert_sequence_modes(&restored, &[(1, [3; 3])]);
        check(
            "persistent dictionary reset",
            &restored,
            &sources[0],
            Some(&path),
        );
        let mut prefix = Encoder::new();
        prefix.set_prefix(dictionary).unwrap();
        let claimed = encode_blocks(&mut prefix, &sources, 1, 1);
        assert_eq!(claimed, restored);
        check("claimed prefix", &claimed, &sources[0], Some(&path));
        prefix.reset();
        let plain = encode_blocks(&mut prefix, &sources, 1, 1);
        assert_sequence_modes(&plain, &[(1, [0; 3])]);
        check("next frame without prefix", &plain, &sources[0], None);
        assert_eq!(checked_frames, 14);
        eprintln!(
            "C decoded {checked_frames} public sequence frames, {checked_bytes} output bytes: predefined/new/RLE/repeat, raw/RLE/empty preservation, singleton dictionaries, reset and prefix isolation"
        );
    }
}
